        for c1 in range(w):
            if grid[r1][c1] != bg_color:
                continue

            # Try all possible bottom-right corners
            for r2 in range(r1 + 1, h):
                for c2 in range(c1 + 1, w):
                    if grid[r2][c2] != bg_color:
                        continue

                    # Check if all cells from (r1,c1) to (r2,c2) are bg_color
                    is_bg_region = True
                    for rr in range(r1, r2 + 1):
                        for cc in range(c1, c2 + 1):
                            if grid[rr][cc] != bg_color:
                                is_bg_region = False
                                break
                        if not is_bg_region:
                            break

                    if not is_bg_region:
                        continue

                    # Check if the rectangle is surrounded by boundary color
                    # Check top edge (r1-1, c1 to c2)
                    # Check bottom edge (r2+1, c1 to c2)
                    # Check left edge (r1 to r2, c1-1)
                    # Check right edge (r1 to r2, c2+1)

                    top_ok = True
                    bottom_ok = True
                    left_ok = True
                    right_ok = True

                    if r1 > 0:  # Not at top edge
                        for cc in range(c1, c2 + 1):
                            if grid[r1 - 1][cc] != bd_color:
                                top_ok = False
                                break

                    if r2 < h - 1:  # Not at bottom edge
                        for cc in range(c1, c2 + 1):
                            if grid[r2 + 1][cc] != bd_color:
                                bottom_ok = False
                                break

                    if c1 > 0:  # Not at left edge
