                                left_ok = False
                                break

                    if c2 < w - 1:  # Not at right edge
                        for rr in range(r1, r2 + 1):
                            if grid[rr][c2 + 1] != bd_color:
                                right_ok = False
                                break

                    if top_ok and bottom_ok and left_ok and right_ok:
                        rectangles.append((r1, c1, r2, c2))

    return rectangles

