from collections import deque

def find_connected_components_of(grid, color):
    """Find connected regions of a given color using 4-connectivity."""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and not visited[r][c]:
                # BFS to find component
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))

                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            if grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                components.append(component)

    return components

